// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address attacker, uint256 value, bytes memory data) public {
        vm.assume(attacker != address(this));

        uint256 seedFund = bound(value, 1, 1 ether);
        vm.deal(address(c), seedFund);

        vm.deal(attacker, 1 gwei);

        bool ok;
        vm.prank(attacker);
        try c.sendMoney(attacker, value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
